import XCTest
@testable import KipurseCore

/// t1281 (handbook §6#141, rule 0A #10): the app's spend-cost formula against the SERVER's own output. The fixture is generated by the
/// gateway (scripts/t1281-spend-cost-fixture.mjs, from src/v5/spend-cost.mjs costOf) and the gateway test fails if it is stale.
/// amount + 0.1% protocol fee + network fee, phone and server identical for every case.
final class T1281SpendCostCrossTests: XCTestCase {
  struct Case: Decodable { let amount: String; let fee: String?; let networkFee: String?; let state: String; let ppm: Int64; let maxNetworkFee, expectedFee, expectedNetworkFee, expected: String }
  struct File: Decodable { let cases: [Case] }
  func load() throws -> [Case] {
    let u = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("t1281-spend-cost.json.txt")
    return try JSONDecoder().decode(File.self, from: Data(contentsOf: u)).cases
  }
  func testPhoneMatchesServerForEveryCase() throws {
    let cs = try load(); XCTAssertGreaterThanOrEqual(cs.count, 40)
    for c in cs {
      let a = Int64(c.amount)!
      let got = SpendCost.cost(amount: a, fee: c.fee.flatMap { Int64($0) }, networkFee: c.networkFee.flatMap { Int64($0) }, ppm: c.ppm,
                               inFlight: SpendCost.inFlight(c.state), maxNetworkFee: Int64(c.maxNetworkFee)!)
      XCTAssertEqual(got, Int64(c.expected)!, "\(c)")
      if c.fee == nil { XCTAssertEqual(SpendCost.protocolFee(amount: a, ppm: c.ppm), Int64(c.expectedFee)!, "fee rounding \(c)") }
    }
  }
  func testFinishedRowWithoutNetworkFeeCountsZeroAndFeeRoundsUp() {
    XCTAssertEqual(SpendCost.cost(amount: 1, fee: nil, networkFee: nil, ppm: 1000), 2)
    XCTAssertEqual(SpendCost.cost(amount: 500_000, fee: nil, networkFee: nil, ppm: 1000), 500_500)
    XCTAssertEqual(SpendCost.cost(amount: 500_000, fee: 500, networkFee: 3_500, ppm: 1000), 504_000)
    XCTAssertEqual(SpendCost.cost(amount: 300_000, fee: nil, networkFee: nil, ppm: 1000, inFlight: true, maxNetworkFee: 50_000), 350_300)
  }
}
